// src/jsx/Contacts.jsx
import useSearchUsers from "../hooks/useSearchUsers";
import { useEffect, useState } from "react";
import { db } from "../js/firebaseConfig";
import { collection, query, onSnapshot } from "firebase/firestore";


function getInitials(nameOrEmail) {
    if (!nameOrEmail) return "?";
    const parts = nameOrEmail.split(" ");
    if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
    return (parts[0][0] + parts[1][0]).toUpperCase();
}

function Avatar({ user, size = 40 }) {
    const style = {
        width: size,
        height: size,
        borderRadius: size / 2,
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        fontWeight: 600,
        fontSize: Math.max(12, size / 3),
        background: "#ddd",
        overflow: "hidden"
    };

    if (!user) return <div style={style}>{getInitials("U")}</div>;

    if (user.avatarUrl) {
        return <img src={user.avatarUrl} alt="avatar" style={{ ...style, objectFit: "cover" }} />;
    }

    const name = user.nome || user.email || "";
    return <div style={style}>{getInitials(name)}</div>;
}


export default function Contacts({ currentUser, setChatUser, setChatGroup, setScreen, logout }) {
    const { filtered, search, searchUsers } = useSearchUsers();
    const [groups, setGroups] = useState([]);


    useEffect(() => {
        const q = query(collection(db, "groups"));
        const unsub = onSnapshot(q, snap => {
            setGroups(snap.docs.map(d => ({ id: d.id, ...d.data() })));
        });
        return () => unsub();
    }, []);

    // Carregar todos os usuários ao abrir
    useEffect(() => {
        searchUsers("");
    }, []);

    const usersToShow = filtered.filter(u => u.id !== currentUser.uid);

    // <-- Agora retorna apenas a SIDEBAR -->
    return (
        <div className="sidebar">

            {/* Header do WhatsApp */}
            <div className="sidebar-header">
                <span>Bem-vindo, {currentUser.email}</span>
                <button className="logout-btn" onClick={logout}>Sair</button>
            </div>

            {/* Busca */}
            <div className="sidebar-search">
                <input
                    placeholder="Pesquisar contatos..."
                    value={search}
                    onChange={e => searchUsers(e.target.value)}
                />
            </div>

            {/* Usuários */}
            <h3 className="section-title">Usuários</h3>

            {usersToShow.map(u => (
                <div
                    key={u.id}
                    className="contact-item"
                    onClick={() => {
                        setChatUser(u);
                        setChatGroup(null);
                        setScreen("private");
                    }}
                    style={{ display: "flex", alignItems: "center", gap: 12 }}
                >
                    <Avatar user={u} size={44} />
                    <div style={{ flex: 1 }}>
                        <div className="contact-name" style={{ fontWeight: 600 }}>{u.nome || u.email}</div>
                        <div style={{ fontSize: 12, color: "#666" }}>{u.email}</div>
                    </div>
                </div>
            ))}

            {/* Grupos */}
            <h3 className="section-title">Grupos</h3>

            {groups.map(g => (
                <div
                    key={g.id}
                    className="contact-item"
                    onClick={() => {
                        setChatGroup(g);
                        setChatUser(null);
                        setScreen("group");
                    }}
                    style={{ display: "flex", alignItems: "center", gap: 12 }}
                >
                    {/* Avatar de grupo: iniciais do nome */}
                    <div style={{
                        width: 44, height: 44, borderRadius: 22, display: "flex",
                        alignItems: "center", justifyContent: "center", background: "#cfcfcf", fontWeight: 700
                    }}>
                        {(g.name || "G").slice(0, 2).toUpperCase()}
                    </div>
                    <div style={{ flex: 1 }}>
                        <div className="contact-name" style={{ fontWeight: 600 }}>{g.name}</div>
                        <div style={{ fontSize: 12, color: "#666" }}>{(g.members && g.members.length) ? `${g.members.length} membros` : ""}</div>
                    </div>
                </div>
            ))}

            <button
                className="create-group-btn"
                onClick={() => setScreen("createGroup")}
            >
                + Criar Grupo
            </button>

        </div>
    );
}
